t.script:
// Template data
var templateId = ;
var variableBlocks = ;

// Initialize GrapesJS
var editor = grapesjs.init({
    container: '#grapesjs-editor',
    height: '100%',
    width: 'auto',
    storageManager: false,
    plugins: ['gjs-preset-webpage'],
    pluginsOpts: {
        'gjs-preset-webpage': {
            blocksBasicOpts: {
                blocks: ['column1', 'column2', 'column3', 'column3-7', 'text', 'link', 'image', 'video'],
                flexGrid: true,
            },
            navbarOpts: false,
            countdownOpts: false,
            formsOpts: false,
        }
    },
    canvas: {
        styles: [
            'https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css',
        ],
    },
    styleManager: {
        sectors: [{
            name: 'Général',
            open: true,
            buildProps: ['float', 'display', 'position', 'top', 'right', 'left', 'bottom'],
        }, {
            name: 'Dimensions',
            open: false,
            buildProps: ['width', 'height', 'max-width', 'min-height', 'margin', 'padding'],
        }, {
            name: 'Typographie',
            open: false,
            buildProps: ['font-family', 'font-size', 'font-weight', 'letter-spacing', 'color', 'line-height', 'text-align', 'text-decoration', 'text-shadow'],
        }, {
            name: 'Décoration',
            open: false,
            buildProps: ['background-color', 'border', 'border-radius', 'box-shadow'],
        }],
    },
});

// Add BLG and variable blocks
var blockManager = editor.BlockManager;

variableBlocks.forEach(function(block) {
    blockManager.add(block.id, {
        label: block.label,
        category: block.category,
        content: block.content,
        attributes: block.attributes || {},
    });
});

// Load existing template content
loadTemplate();

function loadTemplate() {
    fetch('/construction/template/load/' + templateId, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {},
        }),
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.status === 'success') {
            var templateData = data.result.data;
            if (templateData.components && templateData.components.length > 0) {
                editor.setComponents(templateData.components);
                editor.setStyle(templateData.styles || []);
            } else if (templateData.html) {
                editor.setComponents(templateData.html);
                if (templateData.css) {
                    editor.setStyle(templateData.css);
                }
            }
        }
    })
    .catch(error => {
        console.error('Error loading template:', error);
    });
}

function saveTemplate() {
    var html = editor.getHtml();
    var css = editor.getCss();
    var components = JSON.stringify(editor.getComponents());
    var styles = JSON.stringify(editor.getStyle());

    fetch('/construction/template/save', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                template_id: templateId,
                html: html,
                css: css,
                components: components,
                styles: styles,
            },
        }),
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.status === 'success') {
            showNotification('Template enregistré avec succès!', 'success');
        } else {
            showNotification(data.result.message || 'Erreur lors de l\'enregistrement', 'error');
        }
    })
    .catch(error => {
        console.error('Error saving template:', error);
        showNotification('Erreur lors de l\'enregistrement', 'error');
    });
}

function previewTemplate() {
    window.open('/construction/template/preview/' + templateId, '_blank');
}

function showNotification(message, type) {
    var notification = document.getElementById('save-notification');
    notification.textContent = message;
    notification.className = 'save-notification ' + type;
    notification.style.display = 'block';

    setTimeout(function() {
        notification.style.display = 'none';
    }, 3000);
}

// Keyboard shortcut for save (Ctrl+S)
document.addEventListener('keydown', function(e) {
    if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        saveTemplate();
    }
});
